        if len(p)>=2:
            for c in range(min(p),max(p)+1):
                if grid[r][c]==bg: out[r][c]=2
    for c in range(w):
        p=[r for r in range(h) if grid[r][c]==fg]
        if len(p)>=2:
            for r in range(min(p),max(p)+1):
                if grid[r][c]==bg: out[r][c]=2
    return out

